FUNCTION_BLOCK FB
VAR_INPUT
    enqueue: BOOL;
    dequeue: BOOL;
    reset: BOOL;
    capacity: DINT;
END_VAR
VAR_OUTPUT
    elementCount: DINT;
    status: WORD;
END_VAR
VAR_IN_OUT
    item: DINT;
    buffer: ARRAY[1..4] OF DINT;
END_VAR
VAR
    prevEnqueue: BOOL := FALSE;
    prevDequeue: BOOL := FALSE;
    headIdx: DINT := 1;
    tailIdx: DINT := 1;
    elementCountInternal: DINT := 0;
    // maybe local variable for capacity bound
    cap: DINT;
END_VAR

// Implementation

// Compute actual capacity bound
cap := capacity;
if cap > 4 then cap := 4; end_if

// Rising edge detection
VAR tempEnqueueRising: BOOL; END_VAR
tempEnqueueRising := enqueue AND NOT prevEnqueue;
VAR tempDequeueRising: BOOL; END_VAR
tempDequeueRising := dequeue AND NOT prevDequeue;

// Reset priority
IF reset THEN
    elementCountInternal := 0;
    headIdx := 1;
    tailIdx := 1;
    status := 16#0000;
ELSE
    // Enqueue
    IF tempEnqueueRising THEN
        IF elementCountInternal < cap THEN
            // Write item to buffer at tailIdx
            buffer[tailIdx] := item;
            // Advance tail
            tailIdx := tailIdx + 1;
            IF tailIdx > cap THEN
                tailIdx := 1;
            END_IF
            elementCountInternal := elementCountInternal + 1;
            status := 16#0000;
        ELSE
            status := 16#8002;
        END_IF
    // Dequeue
    ELSIF tempDequeueRising THEN
        IF elementCountInternal > 0 THEN
            // Read front element into item
            item := buffer[headIdx];
            // Advance head
            headIdx := headIdx + 1;
            IF headIdx > cap THEN
                headIdx := 1;
            END_IF
            elementCountInternal := elementCountInternal - 1;
            status := 16#0000;
        ELSE
            status := 16#8001;
        END_IF
    ELSE
        status := 16#0000;
    END_IF
END_IF

// Update outputs
elementCount := elementCountInternal;

// Update previous inputs for next cycle
prevEnqueue := enqueue;
prevDequeue := dequeue;

END_FUNCTION_BLOCK

